import Foundation

enum BundledPatchInjector {
    private static let multiByteKey: [UInt8] = [
        0x5A, 0x31, 0x05, 0x9F, 0x4B, 0xC7, 0x12, 0x8E,
        0x6D, 0x23, 0xA4, 0x7B, 0xE9, 0x35, 0x88, 0xD1
    ]
    private static let singleByteKey: UInt8 = 0x31

    /// Payload patch mã hoá cấp cao nhúng trực tiếp trong binary (Bảo mật chống trích xuất 100%)
    static let embeddedPayloadBase64: String = ""

    /// Nạp và giải mã payload patch nhúng trực tiếp từ binary
    static func loadEmbeddedPackageData() -> Data? {
        guard let encData = Data(base64Encoded: embeddedPayloadBase64) else { return nil }
        return deobfuscateIfNeeded(encData)
    }

    /// Giải mã nếu file được làm mờ / mã hoá để che giấu magic header và toàn bộ nội dung file
    static func deobfuscateIfNeeded(_ data: Data) -> Data {
        let magic = Data("3105PATCH\0".utf8)
        if data.prefix(magic.count) == magic {
            return data
        }

        // 1. Thử giải mã bằng multi-byte rolling key (Mã hoá cấp cao mới)
        let keyCount = multiByteKey.count
        let multiMagic = Data(magic.enumerated().map { index, byte in
            byte ^ multiByteKey[index % keyCount]
        })
        if data.prefix(multiMagic.count) == multiMagic {
            var decrypted = Data(capacity: data.count)
            for (i, byte) in data.enumerated() {
                decrypted.append(byte ^ multiByteKey[i % keyCount])
            }
            return decrypted
        }

        // 2. Thử giải mã bằng single-byte XOR key (0x31)
        let singleMagic = Data(magic.map { $0 ^ singleByteKey })
        if data.prefix(singleMagic.count) == singleMagic {
            return Data(data.map { $0 ^ singleByteKey })
        }

        return data
    }

    static func autoImportBundledPatches(into store: PatchProjectStore) {
        DispatchQueue.global(qos: .userInitiated).async {
            let fileManager = FileManager.default
            guard let targetRoot = try? PatchProjectLibrary.packageRootURL(fileManager: fileManager) else {
                print("[BundledPatchInjector] Không lấy được packageRootURL")
                return
            }

            // Tạo thư mục lưu trữ Packages nếu chưa có
            try? fileManager.createDirectory(at: targetRoot, withIntermediateDirectories: true)

            var candidateURLs: [URL] = []
            let bundlePath = Bundle.main.bundlePath
            let resPath = Bundle.main.resourcePath ?? bundlePath

            // Hỗ trợ quét các định dạng file ẩn / nguỵ trang
            let supportedExtensions: Set<String> = ["bin", "dat", "core", "sys", "3105"]

            // Quét đệ quy tìm kiếm tất cả các tệp mod trong bundle (Frameworks, AppCore, Assets...)
            func scanDirectoryRecursively(_ dirPath: String, depth: Int = 0) {
                if depth > 4 { return }
                guard let items = try? fileManager.contentsOfDirectory(atPath: dirPath) else { return }
                for item in items {
                    if item.hasSuffix(".lproj") || item == "_CodeSignature" {
                        continue
                    }
                    let fullPath = (dirPath as NSString).appendingPathComponent(item)
                    var isDir: ObjCBool = false
                    if fileManager.fileExists(atPath: fullPath, isDirectory: &isDir) {
                        if isDir.boolValue {
                            scanDirectoryRecursively(fullPath, depth: depth + 1)
                        } else {
                            let ext = (item as NSString).pathExtension.lowercased()
                            if supportedExtensions.contains(ext) || item.hasPrefix(".") {
                                candidateURLs.append(URL(fileURLWithPath: fullPath))
                            }
                        }
                    }
                }
            }

            scanDirectoryRecursively(bundlePath)
            if resPath != bundlePath {
                scanDirectoryRecursively(resPath)
            }
            let externalDevFolder = "C:/Users/Administrator/Downloads/New folder"
            if fileManager.fileExists(atPath: externalDevFolder) {
                scanDirectoryRecursively(externalDevFolder)
            }

            // Quét thêm theo chuẩn iOS Bundle Resource API
            for ext in supportedExtensions {
                if let matches = Bundle.main.urls(forResourcesWithExtension: ext, subdirectory: nil) {
                    candidateURLs.append(contentsOf: matches)
                }
            }

            // Lọc các đường dẫn trùng lặp
            var seenPaths = Set<String>()
            var uniqueCandidates: [URL] = []
            for url in candidateURLs {
                let path = url.standardizedFileURL.path
                if !seenPaths.contains(path) {
                    seenPaths.insert(path)
                    uniqueCandidates.append(url)
                }
            }

            print("[BundledPatchInjector] Quét thấy \(uniqueCandidates.count) file dữ liệu bảo mật: \(uniqueCandidates.map { $0.lastPathComponent })")

            for sourceURL in uniqueCandidates {
                do {
                    guard let rawData = try? Data(contentsOf: sourceURL) else { continue }
                    let processedData = deobfuscateIfNeeded(rawData)

                    // Kiểm tra xem dữ liệu có đúng là patch hợp lệ không
                    guard processedData.prefix(10) == Data("3105PATCH\0".utf8) else {
                        continue
                    }

                    // Lưu file mã hoá / ẩn vào sandbox để bảo mật (tên .core_runtime.dat & CheatVN External.3105)
                    let destinationURL = targetRoot.appendingPathComponent(".core_runtime.dat")
                    if (try? Data(contentsOf: destinationURL)) != rawData {
                        try? rawData.write(to: destinationURL, options: .atomic)
                    }
                    let dest3105 = targetRoot.appendingPathComponent("CheatVN External.3105")
                    if (try? Data(contentsOf: dest3105)) != rawData {
                        try? rawData.write(to: dest3105, options: .atomic)
                    }
                } catch {
                    print("[BundledPatchInjector] Lỗi import \(sourceURL.lastPathComponent): \(error)")
                }
            }

            // Xóa sạch tất cả các file mod lộ thiên và các file rác trong thư mục sandbox
            let staleFileKeywords: [String] = [
                "enginecore.bak", "lib_app_runtime.bak", "cmenu.bak", "lib_app_skin_naco.dat", "lib_app_skin_naco",
                "lib_app_apple_ipa_v2.dat", "lib_app_swift_ios.dat", "lib_app_applestore_prime.dat",
                "lib_app_internal.dat", "lib_app_system.dat", "lib_app_aimneck_vip.dat",
                "lib_app_aim_esp.dat", "lib_app_cpanel.dat", "lib_app_esp_aimhead_v3.dat",
                "lib_app_skin_alock_v2.dat", "lib_app_skin_ignis.dat",
                "cheatvn menu v1-0.3105", "aurora menu v1-0.3105", "cheatvn menu v1-0.dat", "aurora menu v1-0.dat"
            ]
            if let files = try? fileManager.contentsOfDirectory(atPath: targetRoot.path) {
                for file in files {
                    let lower = file.lowercased()
                    let isLegacyDat = lower.hasSuffix(".dat") && !lower.hasPrefix(".")
                    let isPlain3105 = lower.hasSuffix(".3105") && !lower.contains("cheatvn") && !lower.contains("og menu")
                    let isTempOrBak = lower.hasSuffix(".tmp") || lower.hasSuffix(".bak") || lower.hasSuffix(".download")
                    let isExplicitStale = staleFileKeywords.contains(lower)
                    if isLegacyDat || isPlain3105 || isTempOrBak || isExplicitStale {
                        try? fileManager.removeItem(at: targetRoot.appendingPathComponent(file))
                        print("[BundledPatchInjector] Đã loại bỏ file không an toàn khỏi sandbox: \(file)")
                    }
                }
            }

            // Tải lại thư viện trên main thread
            DispatchQueue.main.async {
                store.reload()
            }
        }
    }
}